// HESC startup safety: if HESC still owns an "HPVC off" (e.g. after a Node-RED or HA restart),
// switch HPVC back on and clear the ownership flag. HPVC must never stay off by accident.
const S = global.get('homeassistant.homeAssistant.states') || {};
const own = S['input_boolean.hesc_owns_hpvc_off'];
if (!own) { node.status({ fill: 'yellow', shape: 'ring', text: 'HA cache not ready — retry' }); return [null, null, { payload: 'retry' }]; }
flow.set('hesc', undefined);
if (own.state !== 'on') { node.status({ fill: 'grey', shape: 'dot', text: 'Startup: nothing to restore' }); return [null, null, null]; }
const ent = (S['input_text.hesc_hpvc_enabled_entity'] && S['input_text.hesc_hpvc_enabled_entity'].state) || 'input_boolean.hpvc_enabled';
node.status({ fill: 'green', shape: 'dot', text: 'Startup: HPVC restored' });
return [
  { payload: { action: 'input_boolean.turn_on', target: { entity_id: [ent] }, data: {} } },
  { payload: { action: 'input_boolean.turn_off', target: { entity_id: ['input_boolean.hesc_owns_hpvc_off'] }, data: {} } },
  null
];

// Home EV Solar Control (HESC) v0.2 — Engine
// Reads a bounded set of entities from the Home Assistant state cache (no API calls,
// no copy of the full state table), runs the release state machine and emits:
//   out1: status/insight updates (HA action payloads)
//   out2: HPVC on/off (HA action payload)       — never in shadow mode
//   out3: ownership flag on/off (HA action payload)
//   out4: history line (JSONL string)
const S = global.get('homeassistant.homeAssistant.states') || {};
const now = Date.now();
const BAD = ['unknown', 'unavailable', 'none', '', undefined, null];
const st = (id) => (id && S[id]) ? S[id].state : undefined;
const attr = (id, a) => (id && S[id] && S[id].attributes) ? S[id].attributes[a] : undefined;
const num = (v) => { const x = parseFloat(v); return isNaN(x) ? null : x; };
const txt = (id) => { const v = st(id); return BAD.includes(v) ? '' : String(v).trim(); };
const nset = (id, d) => { const v = num(st(id)); return v === null ? d : v; };
const on = (id) => st(id) === 'on';

// ---- configuration (HA helpers) ----
const C = {
  enabled: on('input_boolean.hesc_enabled'),
  shadow: st('input_boolean.hesc_shadow_mode') !== 'off',
  useIrr: on('input_boolean.hesc_use_irradiance'),
  fcNow: txt('input_text.hesc_forecast_now_sensor'),
  fc30: txt('input_text.hesc_forecast_30m_sensor'),
  fcAttr: txt('input_text.hesc_forecast_attribute'),
  irr: txt('input_text.hesc_irradiance_sensor'),
  pv: txt('input_text.hesc_pv_power_sensor'),
  grid: txt('input_text.hesc_grid_power_sensor'),
  evConn: txt('input_text.hesc_ev_connected_sensor'),
  evPow: txt('input_text.hesc_ev_power_sensor'),
  evGreen: txt('input_text.hesc_ev_green_energy_sensor'),
  mode: txt('input_text.hesc_charger_mode_entity'),
  ecoVal: txt('input_text.hesc_charger_eco_value') || 'eco_mode',
  hpvcEn: txt('input_text.hesc_hpvc_enabled_entity') || 'input_boolean.hpvc_enabled',
  hpvcLim: txt('input_text.hesc_hpvc_limited_entity') || 'binary_sensor.hpvc_pv_limited',
  pStart: nset('input_number.hesc_p_start', 2500),
  pHold: nset('input_number.hesc_p_hold', 2000),
  irrStart: nset('input_number.hesc_irr_start', 400),
  irrHold: nset('input_number.hesc_irr_hold', 300),
  tStable: nset('input_number.hesc_t_stable', 5) * 60000,
  tStart: nset('input_number.hesc_t_start', 10) * 60000,
  tDip: nset('input_number.hesc_t_dip', 5) * 60000,
  tStop: nset('input_number.hesc_t_stop', 5) * 60000,
  tMax: nset('input_number.hesc_t_max', 240) * 60000,
  cooldown: nset('input_number.hesc_cooldown', 30) * 60000,
  maxAttempts: nset('input_number.hesc_max_attempts', 3),
  activeW: nset('input_number.hesc_ev_active_w', 400),
