// ---- live values ----
const fcVal = (id) => { if (!id) return null; return C.fcAttr ? num(attr(id, C.fcAttr)) : num(st(id)); };
const L = {
  fcNow: fcVal(C.fcNow),
  fc30: fcVal(C.fc30),
  fcMedian: num(st(C.fcNow)),
  irr: C.irr ? num(st(C.irr)) : null,
  pv: num(st(C.pv)),
  grid: num(st(C.grid)),
  evConn: on(C.evConn),
  evPow: num(st(C.evPow)),
  evGreen: C.evGreen ? num(st(C.evGreen)) : null,
  mode: st(C.mode),
  hpvcOn: on(C.hpvcEn),
  hpvcLimited: on(C.hpvcLim),
  sun: st('sun.sun') === 'above_horizon',
  owns: on('input_boolean.hesc_owns_hpvc_off'),
};
const missing = [];
if (L.fcNow === null) missing.push('forecast now');
if (L.fc30 === null) missing.push('forecast +30m');
if (L.pv === null) missing.push('PV power');
if (L.evPow === null) missing.push('EV power');
if (!C.evConn || BAD.includes(st(C.evConn))) missing.push('EV connected');
if (!C.mode || BAD.includes(L.mode)) missing.push('charger mode');
if (BAD.includes(st(C.hpvcEn))) missing.push('HPVC enabled');
const irrUsed = C.useIrr && !!C.irr && L.irr !== null;
const valid = missing.length === 0;

// ---- persistent runtime context ----
const today = new Date(now).toLocaleDateString('sv-SE', { timeZone: 'Europe/Amsterdam' });
let X = flow.get('hesc') || { state: 'IDLE', since: now, stableSince: null, dipSince: null, stopSince: null,
  cooldownUntil: 0, lastTick: now, rel: null, eco: null, acc: null, day: null, last: {} };
if (!X.day || X.day.date !== today) X.day = { date: today, releases: 0, success: 0, failed: 0, ecoSessions: 0, fcWh: 0, pvWh: 0, evWh: 0, greenKwh: 0 };
const dtH = Math.min(Math.max((now - (X.lastTick || now)) / 3600000, 0), 0.05); // cap 3 min
X.lastTick = now;

const evWaiting = L.evConn && L.mode === C.ecoVal && L.evPow !== null && L.evPow <= C.activeW;
const evCharging = L.evPow !== null && L.evPow > C.activeW;
const hpvcBlocks = L.hpvcOn && L.hpvcLimited;
const fcLow = (L.fcNow !== null && L.fc30 !== null) ? Math.min(L.fcNow, L.fc30) : null;
const fcStartOk = fcLow !== null && fcLow >= C.pStart;
const fcHoldOk = fcLow !== null && fcLow >= C.pHold;
const irrStartOk = !irrUsed || L.irr >= C.irrStart;
const irrHoldOk = !irrUsed || L.irr >= C.irrHold;

const msgs1 = [], msgs2 = [], msgs3 = [], msgs4 = [];
const act = (action, entity, data) => ({ payload: { action: action, target: { entity_id: [entity] }, data: data || {} } });
const hist = (o) => msgs4.push({ payload: JSON.stringify(Object.assign({ ts: new Date(now).toISOString(), shadow: C.shadow }, o)) });
const r0 = (v) => v === null || v === undefined ? null : Math.round(v);

function snapshot() {
  return { fc_now: r0(L.fcNow), fc_30m: r0(L.fc30), fc_median: r0(L.fcMedian), irr: r0(L.irr), pv: r0(L.pv), grid: r0(L.grid), ev: r0(L.evPow), mode: L.mode, hpvc_on: L.hpvcOn, hpvc_limited: L.hpvcLimited };
}
function integrate(sess) {
  if (!sess) return;
  if (L.fcMedian !== null) sess.fcWh += L.fcMedian * dtH;
  if (L.pv !== null) sess.pvWh += L.pv * dtH;
  if (L.evPow !== null) sess.evWh += L.evPow * dtH;
}
function closeSession(sess, type, reason) {
  const green = (sess.greenStart !== null && L.evGreen !== null) ? Math.max(0, L.evGreen - sess.greenStart) : null;
  const acc = sess.fcWh > 0 ? Math.round(100 * sess.pvWh / sess.fcWh) : null;
  hist({ type: type, reason: reason, start: new Date(sess.start).toISOString(), minutes: Math.round((now - sess.start) / 60000),
    forecast_wh: Math.round(sess.fcWh), pv_wh: Math.round(sess.pvWh), actual_vs_forecast_pct: acc, ev_wh: Math.round(sess.evWh),
    ev_green_kwh: green === null ? null : Math.round(green * 100) / 100, ev_started: !!sess.evStarted, start_ctx: sess.ctx, end_ctx: snapshot() });
  X.day.fcWh += sess.fcWh; X.day.pvWh += sess.pvWh; X.day.evWh += sess.evWh; if (green !== null) X.day.greenKwh += green;
}
function newSession() { return { start: now, fcWh: 0, pvWh: 0, evWh: 0, greenStart: L.evGreen, evStarted: false, ctx: snapshot() }; }

let reason = '';
function restore(why) {
  if (!C.shadow && L.owns) { msgs2.push(act('input_boolean.turn_on', C.hpvcEn)); msgs3.push(act('input_boolean.turn_off', 'input_boolean.hesc_owns_hpvc_off')); }
  if (X.rel) { if (X.rel.evStarted) X.day.success++; else X.day.failed++; closeSession(X.rel, 'release', why); X.rel = null; }
  X.cooldownUntil = now + C.cooldown;
  X.state = 'IDLE'; X.since = now; X.stableSince = null; X.dipSince = null; X.stopSince = null;
  reason = 'Restored HPVC: ' + why;
}

// ---- manual intervention / disable while owning ----
if (!C.shadow && L.owns && (X.state === 'WAIT_START' || X.state === 'CHARGING') && L.hpvcOn && X.rel && now - X.rel.start > 90000) {
  msgs3.push(act('input_boolean.turn_off', 'input_boolean.hesc_owns_hpvc_off'));
  if (X.rel) { closeSession(X.rel, 'release', 'manual_hpvc_on'); X.rel = null; }
  X.state = 'IDLE'; X.since = now; reason = 'HPVC switched on manually — release abandoned';
}
if (!C.enabled && X.state !== 'IDLE') restore('HESC disabled');

// ---- state machine ----
if (C.enabled && reason === '') {
  if (X.state === 'IDLE') {
    const attemptsLeft = (X.day.releases - X.day.success) < C.maxAttempts;
    const ready = valid && L.sun && evWaiting && hpvcBlocks && fcStartOk && irrStartOk && now >= X.cooldownUntil && attemptsLeft;
    if (ready) {
      X.stableSince = X.stableSince || now;
      if (now - X.stableSince >= C.tStable) {
        X.state = 'WAIT_START'; X.since = now; X.stableSince = null; X.day.releases++;
        X.rel = newSession();
        if (!C.shadow) { msgs2.push(act('input_boolean.turn_off', C.hpvcEn)); msgs3.push(act('input_boolean.turn_on', 'input_boolean.hesc_owns_hpvc_off')); }
        reason = 'Release: HPVC ' + (C.shadow ? 'would be' : 'is') + ' switched off so Eco can start';
      } else reason = 'Conditions met, confirming (' + Math.round((now - X.stableSince) / 60000) + '/' + Math.round(C.tStable / 60000) + ' min)';
    } else {
      X.stableSince = null;
      if (!valid) reason = 'Waiting for inputs: ' + missing.join(', ');
      else if (!L.sun) reason = 'Night';
      else if (!L.evConn) reason = 'No EV connected';
      else if (L.mode !== C.ecoVal) reason = 'Charger not in Eco mode';
      else if (evCharging) reason = 'EV is charging';
      else if (!hpvcBlocks) reason = 'HPVC is not limiting PV — nothing to release';
      else if (!fcStartOk) reason = 'Forecast too low (< ' + C.pStart + ' W)';
      else if (!irrStartOk) reason = 'Irradiance too low (< ' + C.irrStart + ' W/m²)';
      else if (now < X.cooldownUntil) reason = 'Cooldown until ' + new Date(X.cooldownUntil).toLocaleTimeString('nl-NL', { timeZone: 'Europe/Amsterdam', hour: '2-digit', minute: '2-digit' });
      else reason = 'Maximum release attempts reached today';
    }
  } else if (X.state === 'WAIT_START') {
    integrate(X.rel);
    if (!valid) restore('inputs unavailable');
    else if (!L.evConn || L.mode !== C.ecoVal) restore('EV disconnected or not in Eco');
    else if (!L.sun) restore('sunset');
    else if (evCharging) { X.state = 'CHARGING'; X.since = now; X.rel.evStarted = true; reason = 'EV started charging on solar'; }
    else if (now - X.since >= C.tStart) restore('EV did not start within ' + Math.round(C.tStart / 60000) + ' min');
    else reason = 'Waiting for Eco to start (' + Math.round((now - X.since) / 60000) + '/' + Math.round(C.tStart / 60000) + ' min)';
  } else if (X.state === 'CHARGING') {
    integrate(X.rel);
    const holdOk = fcHoldOk && irrHoldOk;
    X.dipSince = holdOk ? null : (X.dipSince || now);
    X.stopSince = evCharging ? null : (X.stopSince || now);
    if (!valid) restore('inputs unavailable');
    else if (!L.evConn || L.mode !== C.ecoVal) restore('EV disconnected or not in Eco');
    else if (!L.sun) restore('sunset');
    else if (X.stopSince && now - X.stopSince >= C.tStop) restore('EV stopped charging');
    else if (X.dipSince && now - X.dipSince >= C.tDip) restore('solar below hold threshold');
    else if (now - X.rel.start >= C.tMax) restore('maximum release duration');
    else reason = 'Release active — EV charging on solar';
  }
}
if (!C.enabled && reason === '') reason = 'HESC disabled';

// ---- independent Eco charge sessions (forecast vs actual while charging on Eco) ----
const ecoCharging = evCharging && L.mode === C.ecoVal && L.sun;
if (ecoCharging && !X.eco) { X.eco = newSession(); X.day.ecoSessions++; }
if (X.eco) integrate(X.eco);
if (!ecoCharging && X.eco) { closeSession(X.eco, 'eco_charge', 'charging ended'); X.eco = null; }

// ---- source reliability: 15-minute daylight intervals (forecast vs actual, irradiance vs PV) ----
// Intervals in which HPVC limited PV are flagged, because curtailed PV says nothing about forecast quality.
const SLOT = 15 * 60000; const slot = Math.floor(now / SLOT) * SLOT;
if (X.acc && X.acc.slot !== slot) {
  const a = X.acc;
  if (a.n >= 10) hist({ type: 'accuracy', slot_start: new Date(a.slot).toISOString(), minutes: 15,
    fc_w: Math.round(a.fc / a.nf), fc10_w: a.n10 ? Math.round(a.fc10 / a.n10) : null, pv_w: Math.round(a.pv / a.np),
    irr_wm2: a.ni ? Math.round(a.irr / a.ni) : null, hpvc_limited_share: Math.round(100 * a.lim / a.n) / 100 });
  X.acc = null;
}
if (L.sun && L.fcMedian !== null && L.pv !== null) {
  const a = X.acc || (X.acc = { slot: slot, n: 0, nf: 0, fc: 0, n10: 0, fc10: 0, np: 0, pv: 0, ni: 0, irr: 0, lim: 0 });
  a.n++; a.nf++; a.fc += L.fcMedian; a.np++; a.pv += L.pv;
  if (C.fcAttr && L.fcNow !== null) { a.n10++; a.fc10 += L.fcNow; }
  if (L.irr !== null) { a.ni++; a.irr += L.irr; }
  if (L.hpvcLimited) a.lim++;
}

// ---- status publication (only on change) ----
const labels = { IDLE: 'Idle', WAIT_START: 'Release — waiting for EV', CHARGING: 'Release — EV charging' };
const stateTxt = (C.shadow ? '[shadow] ' : '') + (C.enabled ? labels[X.state] : 'Disabled');
const d = X.day; const acc = d.fcWh > 0 ? Math.round(100 * d.pvWh / d.fcWh) + '%' : '–';
const insight1 = ('Today: ' + d.releases + ' releases (' + d.success + ' ok, ' + d.failed + ' failed), ' + d.ecoSessions + ' Eco sessions').slice(0, 255);
const insight2 = ('Today: actual PV vs forecast during charging ' + acc + ', EV ' + (d.evWh / 1000).toFixed(1) + ' kWh (' + d.greenKwh.toFixed(1) + ' kWh solar)').slice(0, 255);
const insight3 = ('Now: forecast ' + (r0(fcLow) === null ? '–' : r0(fcLow) + ' W') + (C.irr ? ', irradiance ' + (r0(L.irr) === null ? '–' : r0(L.irr) + ' W/m²') : '') + ', PV ' + (r0(L.pv) === null ? '–' : r0(L.pv) + ' W') + ', HPVC ' + (hpvcBlocks ? 'limiting' : (L.hpvcOn ? 'on' : 'off'))).slice(0, 255);
const pub = { 'input_text.hesc_state': stateTxt, 'input_text.hesc_reason': reason.slice(0, 255), 'input_text.hesc_insight_1': insight1, 'input_text.hesc_insight_2': insight2 };
// insight_3 (live values) is only published together with a state/reason change, to keep HA writes low
if (X.last['input_text.hesc_reason'] !== reason.slice(0, 255)) pub['input_text.hesc_insight_3'] = insight3;
for (const [id, v] of Object.entries(pub)) {
  if (X.last[id] !== v && S[id]) { X.last[id] = v; msgs1.push(act('input_text.set_value', id, { value: v })); }
}
if (reason && reason.startsWith('Re') && X.last.action !== reason) {
  X.last.action = reason;
  const la = (new Date(now).toLocaleTimeString('nl-NL', { timeZone: 'Europe/Amsterdam', hour: '2-digit', minute: '2-digit' }) + ' ' + reason).slice(0, 255);
  if (S['input_text.hesc_last_action']) msgs1.push(act('input_text.set_value', 'input_text.hesc_last_action', { value: la }));
  hist({ type: 'event', text: reason, ctx: snapshot() });
}
flow.set('hesc', X);
global.set('hescRuntime', { state: X.state, since: X.since, cooldownUntil: X.cooldownUntil, day: X.day });
node.status({ fill: X.state === 'IDLE' ? 'grey' : (C.shadow ? 'yellow' : 'green'), shape: 'dot', text: stateTxt + ' · ' + reason.slice(0, 40) });
return [msgs1, msgs2, msgs3, msgs4];

// Clear 'report ready' while a new report is built; pass the request on.
const busy = flow.get('hescReportBusy');
if (busy && Date.now() - busy < 60000) { node.status({ fill: 'yellow', shape: 'ring', text: 'already generating' }); return [null, null]; }
flow.set('hescReportBusy', Date.now());
return [{ payload: { action: 'input_boolean.turn_off', target: { entity_id: ['input_boolean.hesc_report_ready'] }, data: {} } }, { payload: '' }];

// No history file yet: build the report with an empty history.
msg.payload = '';
return msg;

// HESC — Build support report (HTML), on demand. Runs outside the evaluation cycle.
// Input: msg.payload = contents of /homeassistant/hesc-data/history.jsonl ('' if missing)
const S = global.get('homeassistant.homeAssistant.states') || {};
const RT = global.get('hescRuntime') || null;
const VERSION = 'v0.2';
const now = new Date();
const esc = (v) => String(v === null || v === undefined ? '–' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const st = (id) => (id && S[id]) ? S[id].state : undefined;
const fmtT = (iso) => { try { return new Date(iso).toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }); } catch (e) { return iso; } };
const dayOf = (iso) => new Date(iso).toLocaleDateString('sv-SE', { timeZone: 'Europe/Amsterdam' });
const kwh = (wh) => (wh === null || wh === undefined || isNaN(wh)) ? '–' : (wh / 1000).toFixed(2).replace('.', ',');
const pct = (v) => (v === null || v === undefined || isNaN(v)) ? '–' : Math.round(v) + '%';
const qn = (a, p) => { const s = a.filter(x => x !== null && x !== undefined && !isNaN(x)).sort((x, y) => x - y); if (!s.length) return null; return s[Math.min(s.length - 1, Math.max(0, Math.round(p * (s.length - 1))))]; };

// ---- parse history ----
const raw = typeof msg.payload === 'string' ? msg.payload : '';
const rows = []; let bad = 0;
for (const line of raw.split('\n')) { if (!line.trim()) continue; try { rows.push(JSON.parse(line)); } catch (e) { bad++; } }
const sessions = rows.filter(r => r.type === 'release' || r.type === 'eco_charge');
const releases = rows.filter(r => r.type === 'release');
const eco = rows.filter(r => r.type === 'eco_charge');
const events = rows.filter(r => r.type === 'event');
const first = rows.length ? rows[0].ts : null;

// ---- summary (patterns first) ----
const sum = (a, f) => a.reduce((s, r) => s + (Number(r[f]) || 0), 0);
const ecoFc = sum(eco, 'forecast_wh'), ecoPv = sum(eco, 'pv_wh'), ecoEv = sum(eco, 'ev_wh');
const ecoGreen = eco.reduce((s, r) => s + (r.ev_green_kwh === null || r.ev_green_kwh === undefined ? 0 : Number(r.ev_green_kwh)), 0);
const accList = eco.filter(r => r.minutes >= 10).map(r => r.actual_vs_forecast_pct);
const relOk = releases.filter(r => r.ev_started).length;
const relShadow = releases.filter(r => r.shadow).length;

// ---- per day, newest first, trend first ----
const D = {};
for (const r of eco) { const k = dayOf(r.start || r.ts); const d = D[k] || (D[k] = { n: 0, fc: 0, pv: 0, ev: 0, green: 0, rel: 0, relOk: 0 }); d.n++; d.fc += r.forecast_wh || 0; d.pv += r.pv_wh || 0; d.ev += r.ev_wh || 0; d.green += Number(r.ev_green_kwh) || 0; }
for (const r of releases) { const k = dayOf(r.start || r.ts); const d = D[k] || (D[k] = { n: 0, fc: 0, pv: 0, ev: 0, green: 0, rel: 0, relOk: 0 }); d.rel++; if (r.ev_started) d.relOk++; }
const days = Object.keys(D).sort().reverse();
const dayAcc = (k) => D[k].fc > 0 ? 100 * D[k].pv / D[k].fc : null;
let dayRows = '';
days.slice(0, 31).forEach((k, i) => {
  const cur = dayAcc(k), old = i + 1 < days.length ? dayAcc(days[i + 1]) : null;
  let tr = '<span class="mut">–</span>';
  if (cur !== null && old !== null) { const dd = cur - old; tr = Math.abs(dd) < 5 ? '<span class="mut">→</span>' : (dd > 0 ? '<span class="up">↑</span>' : '<span class="dn">↓</span>'); }
  dayRows += '<tr><td>' + esc(k) + '</td><td>' + tr + '</td><td>' + D[k].n + '</td><td>' + kwh(D[k].fc) + '</td><td>' + kwh(D[k].pv) + '</td><td><b>' + pct(cur) + '</b></td><td>' + kwh(D[k].ev) + '</td><td>' + D[k].green.toFixed(2).replace('.', ',') + '</td><td>' + (D[k].rel ? D[k].relOk + '/' + D[k].rel : '–') + '</td></tr>';
});

// ---- accuracy distribution ----
const bins = [[0, 50, '< 50%'], [50, 80, '50–80%'], [80, 100, '80–100%'], [100, 120, '100–120%'], [120, 150, '120–150%'], [150, 1e9, '> 150%']];
const bn = bins.map(b => accList.filter(x => x !== null && x >= b[0] && x < b[1]).length);
const bmax = Math.max(1, ...bn);
let distRows = '';
bins.forEach((b, i) => { distRows += '<div class="bar"><span class="bl">' + b[2] + '</span><span class="bt"><span class="bf" style="width:' + Math.round(100 * bn[i] / bmax) + '%"></span></span><span class="bv">' + bn[i] + '</span></div>'; });

// ---- sessions, newest first ----
